/* prefix_quote • returns blockquote prefix length */
static size_t
prefix_quote(uint8_t *data, size_t size)
{
        size_t i = 0;
        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;

        if (i < size && data[i] == '>') {
                if (i + 1 < size && data[i + 1] == ' ')
                        return i + 2;

                return i + 1;
        }

        return 0;
}

/* prefix_code • returns prefix length for block code*/
static size_t
prefix_code(uint8_t *data, size_t size)
{
        if (size > 3 && data[0] == ' ' && data[1] == ' '
                && data[2] == ' ' && data[3] == ' ') return 4;

        return 0;
}

/* prefix_oli • returns ordered list item prefix */
static size_t
prefix_oli(uint8_t *data, size_t size)
{
        size_t i = 0;

        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;

        if (i >= size || data[i] < '0' || data[i] > '9')
                return 0;

        while (i < size && data[i] >= '0' && data[i] <= '9')
                i++;

        if (i + 1 >= size || data[i] != '.' || data[i + 1] != ' ')
                return 0;

        if (is_next_headerline(data + i, size - i))
                return 0;

        return i + 2;
}

/* prefix_uli • returns unordered list item prefix */
static size_t
prefix_uli(uint8_t *data, size_t size)
{
        size_t i = 0;

        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;

        if (i + 1 >= size ||
                (data[i] != '*' && data[i] != '+' && data[i] != '-') ||
                data[i + 1] != ' ')
                return 0;

        if (is_next_headerline(data + i, size - i))
                return 0;

        return i + 2;
}

/* prefix_dt • returns dictionary definition prefix
 * this is in the form of /\s{0,3}:/ (e.g. "  :", where spacing is optional) */
static size_t
prefix_dt(uint8_t *data, size_t size)
{
        size_t i = 0;

        /* skip up to 3 whitespaces (since it's an indented codeblock at 4) */
        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;
        if (i < size && data[i] == ' ') i++;

        /* if the first character after whitespaces isn't :, it isn't a dt */
        if (i + 1 >= size ||
                data[i] != ':' ||
                data[i + 1] != ' ')
                return 0;

        if (is_next_headerline(data + i, size - i))
                return 0;

        return i + 2;
}

